/**
 * Google Gmail Control with Apps Script
 * 이 스크립트는 Gmail API를 사용하여 이메일을 보내고 받은 이메일을 조회합니다.
 */

// 1. 자신에게 이메일 보내기 (제목: 제목01, 본문: 본문01)
function sendEmailToMyself() {
  try {
    // 사용자의 이메일 주소 가져오기
    const userEmail = Session.getActiveUser().getEmail();

    // 이메일 보내기
    GmailApp.sendEmail(
      userEmail,      // 받는 사람 (자기 자신)
      "제목01",       // 이메일 제목
      "본문01",       // 이메일 본문 (일반 텍스트)
      {
        name: "Apps Script 자동화", // 보낸 사람 표시명 (선택사항)
        htmlBody: "<h2>본문01</h2><p>이 이메일은 Google Apps Script를 통해 자동으로 전송되었습니다.</p>" // HTML 형식 본문 (선택사항)
      }
    );

    Logger.log("이메일이 성공적으로 " + userEmail + "에게 전송되었습니다.");
    return "이메일 전송 성공: " + userEmail;

  } catch (error) {
    Logger.log("이메일 전송 실패: " + error.toString());
    return "이메일 전송 실패: " + error.toString();
  }
}

// 2. 나에게 온 메일 상위 10개의 제목 & 본문 출력하기
function getRecentEmails() {
  try {
    // 받은 편지함에서 최근 이메일 10개 가져오기
    const threads = GmailApp.getInboxThreads(0, 10);

    // 결과를 저장할 배열
    const emails = [];

    // 각 스레드(대화)를 순환하며 처리
    for (let i = 0; i < threads.length; i++) {
      const thread = threads[i];
      const messages = thread.getMessages();

      // 스레드 내의 각 메시지 처리
      for (let j = 0; j < messages.length; j++) {
        const message = messages[j];

        // 이메일 정보 추출
        const email = {
          index: emails.length + 1,
          date: message.getDate(),
          from: message.getFrom(),
          subject: message.getSubject(),
          body: message.getPlainBody().substring(0, 200) + "..." // 본문 일부만 표시 (너무 길 수 있음)
        };

        // 결과 배열에 추가
        emails.push(email);

        // 로그에 출력
        Logger.log("========== 이메일 #" + email.index + " ==========");
        Logger.log("날짜: " + email.date);
        Logger.log("보낸사람: " + email.from);
        Logger.log("제목: " + email.subject);
        Logger.log("본문 일부: " + email.body);
        Logger.log("======================================");
      }

      // 10개 이메일에 도달하면 중단
      if (emails.length >= 10) break;
    }

    return emails;

  } catch (error) {
    Logger.log("이메일 조회 실패: " + error.toString());
    return "이메일 조회 실패: " + error.toString();
  }
}
